impl Document {
    pub(crate) fn compare_assembly_sw_connector(
        &self,
        other: &Document,
        a: &AssemblySwConnector,
        b: &AssemblySwConnector,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sw_connector(other, a.base(), b.base(), path)?;
        if a.get_provider_i_ref() != b.get_provider_i_ref() {
            return Err(format!("{path}: PROVIDER_I_REF mismatch"));
        }
        if a.get_requester_i_ref() != b.get_requester_i_ref() {
            return Err(format!("{path}: REQUESTER_I_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_composition_sw_component_type(
        &self,
        other: &Document,
        a: &CompositionSwComponentType,
        b: &CompositionSwComponentType,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sw_component_type(other, a.base(), b.base(), path)?;
        let list_a = a.get_components();
        let list_b = b.get_components();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: COMPONENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .sw_component_prototypes
                .get(*x)
                .ok_or_else(|| format!("{path}.COMPONENTS[{index}]: id not found in own arena"))?;
            let y = other.sw_component_prototypes.get(*y).ok_or_else(|| {
                format!("{path}.COMPONENTS[{index}]: id not found in other arena")
            })?;
            self.compare_sw_component_prototype(
                other,
                x,
                y,
                &format!("{path}.COMPONENTS[{index}]"),
            )?;
        }
        let list_a = a.get_connectors();
        let list_b = b.get_connectors();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CONNECTORS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.CONNECTORS[{index}] mismatch"));
            }
        }
        let list_a = a.get_constant_value_mapping_refs();
        let list_b = b.get_constant_value_mapping_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: CONSTANT_VALUE_MAPPING_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.CONSTANT_VALUE_MAPPING_REFS[{index}] mismatch"
                ));
            }
        }
        let list_a = a.get_data_type_mapping_refs();
        let list_b = b.get_data_type_mapping_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DATA_TYPE_MAPPING_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.DATA_TYPE_MAPPING_REFS[{index}] mismatch"));
            }
        }
        let list_a = a.get_instantiation_rte_event_props();
        let list_b = b.get_instantiation_rte_event_props();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: INSTANTIATION_RTE_EVENT_PROPS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.INSTANTIATION_RTE_EVENT_PROPS[{index}] mismatch"
                ));
            }
        }
        if a.get_physical_dimension_mapping_ref() != b.get_physical_dimension_mapping_ref() {
            return Err(format!("{path}: PHYSICAL_DIMENSION_MAPPING_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_delegation_sw_connector(
        &self,
        other: &Document,
        a: &DelegationSwConnector,
        b: &DelegationSwConnector,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sw_connector(other, a.base(), b.base(), path)?;
        if a.get_inner_port_i_ref() != b.get_inner_port_i_ref() {
            return Err(format!("{path}: INNER_PORT_I_REF mismatch"));
        }
        if a.get_outer_port_ref() != b.get_outer_port_ref() {
            return Err(format!("{path}: OUTER_PORT_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_instantiation_rte_event_props(
        &self,
        other: &Document,
        a: &InstantiationRTEEventProps,
        b: &InstantiationRTEEventProps,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_refined_event_i_ref() != b.get_refined_event_i_ref() {
            return Err(format!("{path}: REFINED_EVENT_I_REF mismatch"));
        }
        if a.get_short_label() != b.get_short_label() {
            return Err(format!("{path}: SHORT_LABEL mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_instantiation_timing_event_props(
        &self,
        other: &Document,
        a: &InstantiationTimingEventProps,
        b: &InstantiationTimingEventProps,
        path: &str,
    ) -> Result<(), String> {
        self.compare_instantiation_rte_event_props(other, a.base(), b.base(), path)?;
        if a.get_period() != b.get_period() {
            return Err(format!("{path}: PERIOD mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_pass_through_sw_connector(
        &self,
        other: &Document,
        a: &PassThroughSwConnector,
        b: &PassThroughSwConnector,
        path: &str,
    ) -> Result<(), String> {
        self.compare_sw_connector(other, a.base(), b.base(), path)?;
        if a.get_provided_outer_port_ref() != b.get_provided_outer_port_ref() {
            return Err(format!("{path}: PROVIDED_OUTER_PORT_REF mismatch"));
        }
        if a.get_required_outer_port_ref() != b.get_required_outer_port_ref() {
            return Err(format!("{path}: REQUIRED_OUTER_PORT_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_sw_component_prototype(
        &self,
        other: &Document,
        a: &SwComponentPrototype,
        b: &SwComponentPrototype,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_prototype(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_type_t_ref() != b.get_type_t_ref() {
            return Err(format!("{path}: TYPE_T_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_sw_connector(
        &self,
        other: &Document,
        a: &SwConnector,
        b: &SwConnector,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_mapping_ref() != b.get_mapping_ref() {
            return Err(format!("{path}: MAPPING_REF mismatch"));
        }
        Ok(())
    }
}
